// @name Hacker News
// @background #f6f6ef
// @refresh 900
// A Hacker News reader drawn like news.ycombinator.com: the front page, new,
// ask, show and jobs, a story's comments with collapsible threads, and user
// pages. Tap or click a story for its comments, a comment to collapse it, the
// title on a story's page for its link as a QR code. With keys or a frame's
// buttons: next / prev (Tab / Shift+Tab) walk the ring, Enter opens, a long
// press of the green key or Backspace goes back. The list refreshes on the
// scene's interval; keys and taps never fetch it again.
import type { Comment, Nav, Story, View } from './hn'
import {
  SECTION_LINKS,
  back,
  current,
  dateText,
  hiddenFlags,
  keyAction,
  parseCommentHtml,
  push,
  readNav,
  section,
  siteOf,
  startNav,
  threadPages,
  timeAgo,
  turn,
} from './hn'
import type { ListData, ThreadData, UserData } from './data'
import { fetchList, fetchThread, fetchUser } from './data'

// ------------------------------------------------------------------ looks

// The site's own colors on a screen; on color e-paper the same without the
// faint tints a panel would dither, the bar in the panel's red ink (its
// orange is a dither of red and yellow that thin letters vanish in), its
// words white and bold; black on white where the panel shows no color, or
// when the Contrast setting asks for it.
const THEMES = {
  color: {
    name: 'color',
    outer: 'bg-white',
    page: 'bg-[#f6f6ef] text-black',
    bar: 'bg-[#ff6600] text-black',
    barSel: 'text-white',
    logoFill: '#ff6600',
    logoInk: '#ffffff',
    title: 'text-black',
    visited: 'text-[#828282]',
    sub: 'text-[#828282]',
    arrow: '#9a9a9a',
    rule: 'bg-[#ff6600]',
    code: 'text-black',
    link: 'text-black underline',
    hover: 'hover:underline',
  },
  paper: {
    name: 'paper',
    outer: 'bg-white',
    page: 'bg-white text-black',
    bar: 'bg-[#ff0000] text-white font-bold',
    barSel: 'underline',
    logoFill: '#ff0000',
    logoInk: '#ffffff',
    title: 'text-black',
    visited: 'text-black',
    sub: 'text-black',
    arrow: '#000000',
    rule: 'bg-[#ff0000]',
    code: 'text-black',
    link: 'text-black underline',
    hover: '',
  },
  high: {
    name: 'high',
    outer: 'bg-white',
    page: 'bg-white text-black',
    bar: 'bg-black text-white',
    barSel: 'text-white underline',
    logoFill: '#000000',
    logoInk: '#ffffff',
    title: 'text-black',
    visited: 'text-black',
    sub: 'text-black',
    arrow: '#000000',
    rule: 'bg-black',
    code: 'text-black',
    link: 'text-black underline',
    hover: '',
  },
}
type Theme = (typeof THEMES)['color']

function themeOf(app): Theme {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return THEMES.high
  if (mode === 'color') return THEMES.color
  return app.frame.paper ? THEMES.paper : THEMES.color
}

// Sizes from one base: the title's text, as HN's 10pt Verdana is to its
// page. Worked out from the panel (a big e-paper reads from across the room)
// and the Text size setting.
const TEXT_SCALES = { small: 0.82, normal: 1, large: 1.25, huge: 1.6 }
interface Sizes {
  key: string
  base: number
  small: number
  sub: number
  text: number
  bar: number
  pad: number
  gap: number
  arrow: number
  rank: number
  indent: number
  maxIndent: number
  logo: number
}
let sizesKept: Sizes | null = null
function sizesOf(app, W: number, H: number): Sizes {
  const scale = TEXT_SCALES[app.state.textSize] ?? 1
  const base = Math.round(Math.min(44, Math.max(Math.min(W, H) >= 400 ? 17 : 15, Math.min(W, H) / 34)) * scale)
  const key = `${base}:${W}`
  if (sizesKept && sizesKept.key === key) return sizesKept
  const r = (k: number) => Math.max(1, Math.round(base * k))
  sizesKept = {
    key,
    base,
    small: r(0.82),
    sub: r(0.76),
    text: r(0.92),
    bar: r(1.9),
    pad: r(0.5),
    gap: r(0.42),
    arrow: r(0.72),
    rank: r(2.3),
    indent: r(1.6),
    maxIndent: Math.round(W * 0.4),
    logo: r(1.3),
  }
  return sizesKept
}

// --------------------------------------------------------------- the place

// The views walked through, kept so a frame drawn on its server (a fresh
// process every time) and an ESP32 that slept come back to the same place.
// Everything kept is read back from frameos.remember at each whole render: a
// module variable may outlive what it mirrors (a scene loaded again).
let navKept: Nav | null = null
const navOf = (app): Nav => (navKept = readNav(frameos.recall('nav'), app.state.startView || 'top'))
const nowSeconds = () => Math.floor(Date.now() / 1000)
const opened = (view: View) => go(push(navKept as Nav, view))
function go(nav: Nav) {
  navKept = nav
  frameos.remember('nav', nav)
  touched()
}
// When someone last did something here: the reader goes back to its first
// page a while after (the Back to the front page setting).
const touched = () => frameos.remember('touched', nowSeconds())

// Stories opened, grey in the list as HN's visited links are.
const seenOf = (): number[] => (frameos.recall('seen') as number[]) || []
function markSeen(id: number) {
  const seen = seenOf().filter((other) => other !== id)
  seen.push(id)
  frameos.remember('seen', seen.slice(-100))
}

// ----------------------------------------------------------------- the data

// One of each kept with frameos.remember: the list, the thread and the user
// last shown. Fetched again when older than `maxAge`; a fetch that fails
// keeps what there was and says so.
interface Kept<T> {
  key: string
  data: T | null
  error: string
  tried: number
}
let forceFresh = false

function load<T extends { at: number }>(kind: string, key: string, maxAge: number, fetcher: () => T): Kept<T> {
  const recalled = frameos.recall(kind) as any
  const kept: Kept<T> = recalled && recalled.key === key ? recalled : { key, data: null, error: '', tried: 0 }
  const now = nowSeconds()
  const stale = !kept.data || forceFresh || now - kept.data.at > maxAge
  // After a failure, wait a minute before asking again (a key press is no
  // reason to hammer an API that is down).
  if (stale && (forceFresh || now - kept.tried > 60)) {
    kept.tried = now
    try {
      kept.data = fetcher()
      kept.error = ''
    } catch (error) {
      kept.error = String((error && error.message) || error)
    }
    if (!frameos.remember(kind, kept)) frameos.log(`Hacker News: ${kind} too big to keep`)
  }
  return kept
}

// How much this frame takes at once. An ESP32 parses a whole comment tree in
// a few MB, so a long thread comes a few subtrees at a time; and every
// character on a page costs it memory to lay out, which a big panel's canvas
// has taken (the 13.3" E1004 keeps about 1.5 MB for a scene): a page there
// is what fits on the screen, a story list half of HN's.
const bigPanel = (app) => app.frame.embedded && app.frame.width * app.frame.height * (app.frame.scale || 1) ** 2 > 1200000
function threadLimits(app) {
  if (!app.frame.embedded) return { maxComments: 500, maxChars: 8000, wholeUpTo: 4000, page: 40, pageChars: 24000 }
  return { maxComments: 120, maxChars: 1500, wholeUpTo: 500, page: 12, pageChars: bigPanel(app) ? 1400 : 3500 }
}
const storiesPerPage = (app) => (bigPanel(app) ? 15 : 30)

// ------------------------------------------------------------- comment page

// A tap that collapses a comment runs only the comments it changes: one
// signal per comment for its fold and one for whether a fold above hides it
// (docs/jsx-ui.md "Signals"). Made again only when the page shows others.
let page = {
  key: '',
  gen: 0,
  comments: [] as Comment[],
  start: 0,
  end: 0,
  storyId: 0,
  fold: [] as any[],
  hide: [] as any[],
}
const foldsOf = (storyId: number): Set<number> => {
  const recalled = frameos.recall('folds') as any
  return new Set(recalled && recalled.id === storyId ? recalled.ids : [])
}

function preparePage(storyId: number, comments: Comment[], start: number, end: number, key: string) {
  const folded = foldsOf(storyId)
  const hidden = hiddenFlags(comments, folded)
  const same =
    page.key === key &&
    page.fold.length === end - start &&
    page.fold.every((fold, j) => fold.peek() === folded.has(comments[start + j].id) && page.hide[j].peek() === hidden[start + j])
  if (same) {
    // The same page read back again: the signals stay (the comments the
    // last whole render drew are subscribed to them).
    page.comments = comments
    return
  }
  const fold = []
  const hide = []
  for (let i = start; i < end; i++) {
    fold.push(signal(folded.has(comments[i].id)))
    hide.push(signal(hidden[i]))
  }
  page = { key, gen: page.gen + 1, comments, start, end, storyId, fold, hide }
}

function toggleFold(local: number) {
  const { comments, start, storyId } = page
  const comment = comments[start + local]
  const folded = foldsOf(storyId)
  if (folded.has(comment.id)) folded.delete(comment.id)
  else folded.add(comment.id)
  frameos.remember('folds', { id: storyId, ids: [...folded] })
  touched()
  page.fold[local].value = folded.has(comment.id)
  const hidden = hiddenFlags(comments, folded)
  for (let j = local + 1; j < page.fold.length && comments[start + j].depth > comment.depth; j++) {
    page.hide[j].value = hidden[start + j]
  }
}

// --------------------------------------------------------------- the pieces

const Arrow = ({ size, color, hidden }: { size: number; color: string; hidden?: boolean }) => (
  <svg viewBox="0 0 10 10" className={`w-[${size}px] h-[${size}px] shrink-0`}>
    {hidden ? null : <path d="M5 1.5L9.2 8.6H0.8Z" fill={color} />}
  </svg>
)

const Logo = ({ size, fill, ink }: { size: number; fill: string; ink: string }) => (
  <svg viewBox="0 0 18 18" className={`w-[${size}px] h-[${size}px] shrink-0`}>
    <rect x="0.5" y="0.5" width="17" height="17" fill={fill} stroke={ink} strokeWidth="1" />
    <path d="M4.6 3.8L9 10.2L13.4 3.8M9 10.2V14.6" fill="none" stroke={ink} strokeWidth="2.1" />
  </svg>
)

// Whether the site's name fits in a bar `width` wide beside its sections:
// the Ubuntu face's letters are about 0.55 of the size wide (0.62 bold).
function nameFits(z: Sizes, width: number) {
  const sections = SECTION_LINKS.reduce((n, s) => n + s.label.length, 0) * 0.55 * z.base
  const bars = (SECTION_LINKS.length - 1) * (0.3 * z.base + 2 * Math.round(z.base * 0.3))
  const name = 'Hacker News'.length * 0.62 * z.base + z.gap
  return 2 * z.gap + z.logo + z.gap / 2 + name + sections + bars <= width
}

// The orange bar. It comes last in the tree (drawn over the top of the page)
// so the keys reach the stories first and go back from the first story to
// the bar. Where there is a page to go back to, "‹ back" takes the left side
// in place of the site's name and its sections. Where the bar is too narrow
// for both (a watch, a small round panel), the logo stands for the name, as
// it takes you to the front page too.
function Header({ t, z, sel, canGoBack, left, right, top, width }) {
  const named = nameFits(z, width)
  const link = (id: string, label: string, onClick: () => void) => (
    <span className={`cursor-pointer ${sel === id ? t.barSel : ''}`} onClick={onClick}>
      {label}
    </span>
  )
  return (
    <div className={`absolute top-[${top}px] left-[${left}px] right-[${right}px] h-[${z.bar}px] flex items-center gap-[${Math.round(z.gap / 2)}px] px-[${z.gap}px] text-[${z.base}px] whitespace-nowrap overflow-hidden ${t.bar}`}>
      {named || canGoBack ? (
        <Logo size={z.logo} fill={t.logoFill} ink={t.logoInk} />
      ) : (
        <span className="flex cursor-pointer" onClick={() => go(section(navKept as Nav, 'top'))}>
          <Logo size={z.logo} fill={t.logoFill} ink={t.logoInk} />
        </span>
      )}
      {canGoBack ? (
        <span className={`font-bold cursor-pointer pr-[${z.gap}px] ${sel === 'back' ? t.barSel : ''}`} onClick={() => go(back(navKept as Nav))}>
          ‹ back
        </span>
      ) : (
        <span className="flex items-center">
          {named ? (
            <span className={`font-bold cursor-pointer pr-[${z.gap}px]`} onClick={() => go(section(navKept as Nav, 'top'))}>
              Hacker News
            </span>
          ) : null}
          {SECTION_LINKS.map((s, i) => (
            <span className="flex items-center">
              {i > 0 ? <span className={`px-[${Math.round(z.base * 0.3)}px]`}>|</span> : null}
              {link(s.id, s.label, () => go(section(navKept as Nav, s.id)))}
            </span>
          ))}
        </span>
      )}
    </div>
  )
}

// The line under a story's title: the points, the author, the age and the
// comments.
const subText = (story: Story, now: number) =>
  story.kind === 'job'
    ? timeAgo(story.time, now)
    : `${story.score} point${story.score === 1 ? '' : 's'} by ${story.by} ${timeAgo(story.time, now)} | ${
        story.comments ? `${story.comments} comment${story.comments === 1 ? '' : 's'}` : 'discuss'
      }`

// A story as HN draws it: the rank, the arrow, the title and its site, and
// under it the points, the author, the age and the comments.
const StoryRow = memo(({ story, rank, seen, look, t, z, tapOpens, now, h }: {
  story: Story
  rank: number
  seen: boolean
  look: string
  t: Theme
  z: Sizes
  tapOpens: string
  now: number
  h?: number
}) => {
  const site = siteOf(story.url)
  const open = () => {
    markSeen(story.id)
    opened({ v: 'item', id: story.id, p: 0 })
  }
  const title = (
    <div className={`text-[${z.base}px] leading-[1.25] ${seen ? t.visited : t.title}`}>
      {story.title}
      {site ? <span className={`text-[${z.small}px] ${t.sub}`}>{` (${site})`}</span> : null}
    </div>
  )
  const sub = (
    <div className={`text-[${z.sub}px] leading-[1.3] ${t.sub}`}>{subText(story, now)}</div>
  )
  // One stop for the keys a story: the whole story opens its comments. With
  // "Tap a story: its link", the title is the link (its QR code) and the line
  // under it the comments.
  return (
    <div className={`flex items-start gap-[${z.gap}px] px-[${z.gap}px] py-[${Math.round(z.pad / 2)}px] ${h ? `h-[${h}px] shrink-0` : ''} cursor-pointer`}
      onClick={tapOpens === 'link' && story.url ? undefined : open}>
      <span className={`w-[${z.rank}px] shrink-0 text-right text-[${z.base}px] leading-[1.25] ${t.sub}`}>{`${rank}.`}</span>
      <div className={`pt-[${Math.round(z.base * 0.2)}px]`}>
        <Arrow size={z.arrow} color={t.arrow} hidden={story.kind === 'job'} />
      </div>
      <div className="flex-1 min-w-0 flex flex-col">
        {tapOpens === 'link' && story.url ? <a href={story.url} className={t.hover}>{title}</a> : title}
        {tapOpens === 'link' && story.url ? <div onClick={open}>{sub}</div> : sub}
      </div>
    </div>
  )
})

// A comment's text: paragraphs of runs (italics, links) and code blocks.
function Body({ html, t, z }: { html: string; t: Theme; z: Sizes }) {
  const blocks = parseCommentHtml(html)
  return (
    <div className={`flex flex-col gap-[${z.gap}px] text-[${z.text}px] leading-[1.35] overflow-hidden`}>
      {blocks.map((block) =>
        block.kind === 'pre' ? (
          <div className={`flex flex-col font-mono text-[${z.sub}px] leading-[1.3] pl-[${z.gap * 2}px] overflow-x-auto ${t.code}`}>
            {block.lines.map((line) => (
              <div className="whitespace-nowrap">{line.replace(/^ +/, (s) => ' '.repeat(s.length)) || ' '}</div>
            ))}
          </div>
        ) : (
          <div>
            {block.runs.map((run) =>
              run.href ? (
                <a href={run.href} className={t.link}>{run.text}</a>
              ) : run.italic ? (
                <i>{run.text}</i>
              ) : (
                run.text
              ),
            )}
          </div>
        ),
      )}
    </div>
  )
}

// One comment of the page showing. Its fold and whether a fold above hides it
// are signals: a tap runs this comment and the ones under it, nothing else.
const CommentRow = memo(({ i, gen, look, t, z, now }: {
  i: number
  gen: number
  look: string
  t: Theme
  z: Sizes
  now: number
}) => {
  const comment = page.comments[page.start + i]
  const folded = page.fold[i].value
  const hidden = page.hide[i].value
  const indent = Math.min(z.maxIndent, comment.depth * z.indent)
  return (
    <div className={hidden ? 'hidden' : `flex items-start gap-[${z.gap}px] pl-[${indent + z.gap}px] pr-[${z.pad}px] py-[${z.pad}px] cursor-pointer`}
      onClick={() => toggleFold(i)}>
      <div className={`pt-[${Math.round(z.small * 0.15)}px]`}>
        <Arrow size={z.arrow} color={t.arrow} hidden={comment.dead} />
      </div>
      <div className="flex-1 min-w-0 flex flex-col gap-[2px]">
        <div className={`text-[${z.small}px] leading-[1.3] ${t.sub}`}>
          {comment.dead ? '[deleted]' : `${comment.by} ${timeAgo(comment.time, now)}`}
          {folded ? ` [${comment.more + 1} more]` : ' [–]'}
        </div>
        {folded || comment.dead ? null : <Body html={comment.html} t={t} z={z} />}
      </div>
    </div>
  )
})

function Pager({ t, z, label, onClick }) {
  return (
    <div className={`flex gap-[${z.gap}px] px-[${z.gap}px] py-[${z.pad}px]`}>
      <span className={`w-[${z.rank + z.arrow + z.gap}px] shrink-0`} />
      <span className={`text-[${z.base}px] cursor-pointer ${t.title} ${t.hover}`} onClick={onClick}>{label}</span>
    </div>
  )
}

function Footer({ t, z, note }) {
  return (
    <div className={`flex flex-col items-center gap-[${z.gap}px] pt-[${z.pad * 2}px] pb-[${z.pad * 3}px]`}>
      <div className={`w-full h-[2px] ${t.rule}`} />
      <div className={`text-[${z.sub}px] ${t.sub}`}>{note}</div>
    </div>
  )
}

function Problem({ t, z, error, retry }) {
  return (
    <div className={`flex flex-col gap-[${z.pad}px] p-[${z.pad * 2}px] text-[${z.base}px]`}>
      <div>{`Could not reach Hacker News: ${error}`}</div>
      <span className={`underline cursor-pointer ${t.title}`} onClick={retry}>Try again</span>
    </div>
  )
}

const retry = () => {
  forceFresh = true
  touched()
}

// ------------------------------------------------------------------- views

// On a panel that draws slowly the list is read as a page, so its box ends
// under the last story it shows whole, not through one; the keys page on
// from there. Each row is as tall as it measures, so the rows end where the
// sum says: the site, drawn at 0.82 of the title's size, measured as a few
// letters more than that share of it in the title's (a row a line too tall
// is a gap, a line too short would run into the next). Null where the list
// fits, or the panel is fast.
let listFit: { box: number; rows: number[] } | null = null
function fitList(app, stories: Story[], z: Sizes, width: number, room: number, now: number) {
  if (app.frame.fast !== false || !stories.length) return null
  const textW = width - 4 * z.gap - z.rank - z.arrow - 2
  const titles = frameos.measureText(
    stories.map((story) => {
      const site = siteOf(story.url)
      return site ? `${story.title} (${site.slice(0, Math.ceil(site.length * 0.82) + 3)})` : story.title
    }),
    { className: `text-[${z.base}px] leading-[1.25]`, width: textW },
  )
  const subs = frameos.measureText(stories.map((story) => subText(story, now)), { className: `text-[${z.sub}px] leading-[1.3]`, width: textW })
  const pad = 2 * Math.round(z.pad / 2)
  const rows = stories.map((story, i) => Math.max(titles[i] + subs[i], Math.round(z.base * 1.25)) + pad)
  let used = z.pad
  for (let i = 0; i < rows.length; i++) {
    if (used + rows[i] > room) return i > 0 ? { box: used, rows } : null
    used += rows[i]
  }
  return null
}

function ListView(app, view: { s: string; p: number }, t: Theme, z: Sizes, look: string, now: number, room?: { width: number; height: number }) {
  const kept = load<ListData>('list', `${view.s}:${view.p}:${storiesPerPage(app)}`, maxAge(app), () =>
    fetchList(view.s, view.p, storiesPerPage(app)),
  )
  const data = kept.data
  if (!data) return <Problem t={t} z={z} error={kept.error} retry={retry} />
  const seen = new Set(seenOf())
  const tapOpens = app.state.storyTap || 'comments'
  if (room) listFit = fitList(app, data.stories, z, room.width, room.height, now)
  return (
    <div className={`flex flex-col pt-[${z.pad}px]`}>
      {data.stories.map((story, i) => (
        <StoryRow key={story.id} story={story} rank={view.p * storiesPerPage(app) + i + 1} seen={seen.has(story.id)} look={look}
          t={t} z={z} tapOpens={tapOpens} now={now} h={listFit ? listFit.rows[i] : undefined} />
      ))}
      {view.p + 1 < data.pages ? (
        <Pager t={t} z={z} label="More" onClick={() => go(turn(navKept as Nav, 1, data.pages))} />
      ) : null}
      <Footer t={t} z={z} note={kept.error ? `Showing the list from ${timeAgo(data.at, now)}: ${kept.error}` : `Updated ${timeAgo(data.at, now)}`} />
    </div>
  )
}

function ItemView(app, view: { id: number; p: number; from?: number }, t: Theme, z: Sizes, look: string, now: number) {
  const limits = threadLimits(app)
  const from = view.from || 0
  const kept = load<ThreadData>('thread', `${view.id}:${from}`, maxAge(app), () => fetchThread(view.id, limits, from))
  const data = kept.data
  if (!data) return <Problem t={t} z={z} error={kept.error} retry={retry} />
  const story = data.story
  const site = siteOf(story.url)
  const starts = threadPages(data.comments, limits.page, limits.pageChars)
  const p = Math.min(view.p, starts.length - 1)
  const start = starts[p]
  const end = p + 1 < starts.length ? starts[p + 1] : data.comments.length
  preparePage(story.id, data.comments, start, end, `${kept.key}:${p}:${data.at}`)
  const titleLine = (
    <div className={`text-[${z.base}px] leading-[1.25] ${t.title}`}>
      {story.title}
      {site ? <span className={`text-[${z.small}px] ${t.sub}`}>{` (${site})`}</span> : null}
    </div>
  )
  const openUser = () => opened({ v: 'user', id: story.by })
  return (
    <div className={`flex flex-col pt-[${z.pad}px]`}>
      <div className={`flex items-start gap-[${z.gap}px] px-[${z.gap}px]`}>
        <div className={`pt-[${Math.round(z.base * 0.2)}px]`}>
          <Arrow size={z.arrow} color={t.arrow} hidden={story.kind === 'job'} />
        </div>
        <div className="flex-1 min-w-0 flex flex-col">
          {story.url ? <a href={story.url} className={`cursor-pointer ${t.hover}`}>{titleLine}</a> : titleLine}
          <div className={`flex flex-wrap text-[${z.sub}px] leading-[1.3] ${t.sub}`}>
            {story.kind === 'job' ? null : <span>{`${story.score} point${story.score === 1 ? '' : 's'} by `}</span>}
            {story.kind === 'job' ? null : <span className={`cursor-pointer ${t.hover}`} onClick={openUser}>{story.by}</span>}
            <span>{` ${timeAgo(story.time, now)}`}</span>
            {story.kind === 'job' ? null : <span>{` | ${story.comments} comment${story.comments === 1 ? '' : 's'}`}</span>}
          </div>
          {data.text ? (
            <div className={`pt-[${z.pad}px]`}>
              <Body html={data.text} t={t} z={z} />
            </div>
          ) : null}
        </div>
      </div>
      <div className={`h-[${z.pad * 2}px]`} />
      {data.comments.slice(start, end).map((comment, i) => (
        <CommentRow key={comment.id} i={i} gen={page.gen} look={look} t={t} z={z} now={now} />
      ))}
      {!data.comments.length ? <div className={`px-[${z.pad * 2}px] text-[${z.text}px] ${t.sub}`}>No comments yet.</div> : null}
      {p + 1 < starts.length ? (
        <Pager t={t} z={z} label="More" onClick={() => go(turn(navKept as Nav, 1, starts.length))} />
      ) : data.cut ? (
        <Pager t={t} z={z} label="More comments"
          onClick={() => opened({ v: 'item', id: view.id, p: 0, from: data.next })} />
      ) : null}
      <Footer t={t} z={z} note={starts.length > 1 ? `Page ${p + 1} of ${starts.length}` : kept.error ? kept.error : ''} />
    </div>
  )
}

function UserView(app, view: { id: string }, t: Theme, z: Sizes, now: number) {
  const kept = load<UserData>('user', view.id, 86400, () => fetchUser(view.id))
  const data = kept.data
  if (!data) return <Problem t={t} z={z} error={kept.error} retry={retry} />
  const row = (label: string, value: any) => (
    <div className={`flex gap-[${z.pad}px] text-[${z.base}px] leading-[1.35]`}>
      <span className={`w-[${z.base * 5}px] shrink-0 ${t.sub}`}>{label}</span>
      <div className="flex-1 min-w-0">{value}</div>
    </div>
  )
  return (
    <div className={`flex flex-col gap-[${z.gap}px] p-[${z.pad * 2}px]`}>
      {row('user:', <span className="font-bold">{data.id}</span>)}
      {row('created:', data.created ? `${dateText(data.created)} (${timeAgo(data.created, now)})` : '')}
      {row('karma:', String(data.karma))}
      {data.about ? row('about:', <Body html={data.about} t={t} z={z} />) : null}
    </div>
  )
}

// The list is fetched again when it is older than the scene's interval, so
// each render the interval asks for gets a fresh one and taps never do.
const maxAge = (app) => Math.max(60, Math.min(3600, (Number(app.state.refreshInterval) || 900) * 0.9))

// ---------------------------------------------------------------- the scene

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const t = themeOf(app)
  const z = sizesOf(app, W, H)
  const look = `${t.name}:${z.key}`
  const now = nowSeconds()
  // The ages ("3 hours ago") by the minute, so a story's row is the same
  // element from one render to the next within it.
  const minute = now - (now % 60)

  // Back to the first page when nobody has touched the frame for a while.
  let nav = navOf(app)
  const idle = Number(app.state.returnAfter ?? 30)
  const lastTouch = Number(frameos.recall('touched') || 0)
  if (idle > 0 && lastTouch && now - lastTouch > idle * 60 && (nav.stack.length > 1 || current(nav).v !== 'list' || (current(nav) as any).p > 0)) {
    nav = startNav(app.state.startView || 'top')
    navKept = nav
    frameos.remember('nav', nav)
  }
  const view = current(nav)
  // On a wide screen the page is HN's on a desktop: 85% of the width, centered,
  // a little way down from the top.
  const round = context?.round === true
  const wide = W >= 1280
  const margin = wide ? Math.round(W * 0.075) : 0
  const top = wide ? Math.round(z.base * 0.6) : 0
  listFit = null
  let body
  try {
    body =
      view.v === 'list'
        ? ListView(app, view, t, z, look, minute, round ? undefined : { width: W - 2 * margin, height: H - z.bar - top })
        : view.v === 'item'
          ? ItemView(app, view, t, z, look, minute)
          : UserView(app, view, t, z, minute)
  } finally {
    forceFresh = false
  }
  // On a round panel the orange bar is a cap over the top of the circle, its
  // links where the circle is wide enough for them, and the page scrolls in
  // the room the circle leaves under it.
  if (round) {
    const R = Math.min(W, H) / 2 - 12
    const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
    const barTop = Math.round(H / 2 - R * 0.72)
    const barMargin = Math.max(0, Math.round((W - chord(R * 0.72)) / 2))
    const pageTop = barTop + z.bar
    const pageBottom = Math.round(H / 2 + R * 0.7)
    const pageW = chord(Math.max(H / 2 - pageTop, pageBottom - H / 2))
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-0 top-0 w-[${W}px] h-[${pageTop}px] ${t.bar}`} />
        <div className={`absolute left-[${Math.round((W - pageW) / 2)}px] top-[${pageTop}px] w-[${pageW}px] h-[${pageBottom - pageTop}px] flex flex-col`}>
          {nav.stack.slice(1).map(() => <span className="hidden" />)}
          <div className={`flex-1 min-h-0 overflow-y-auto ${t.page}`} scrollTop={view.left ? undefined : nav.n % 2 ? '0' : '0.0'}>
            {nav.n % 2 ? <span className="hidden" /> : null}
            {body}
          </div>
        </div>
        <Header t={t} z={z} sel={view.v === 'list' ? view.s : ''} canGoBack={nav.stack.length > 1} left={barMargin} right={barMargin} top={barTop} width={W - 2 * barMargin} />
      </div>
    )
  }
  return (
    <div className={`relative w-full h-full ${t.outer}`}>
      <div className={`flex flex-col h-full ${wide ? `mx-[${margin}px]` : 'w-full'} ${t.outer}`}>
        <div className={`h-[${z.bar + top}px] shrink-0`} />
        {/* Each page of the stack scrolls in a box of its own place in the
            tree, so the layout keeps where each was scrolled to and Back comes
            back there. A page opened anew starts at the top: scrollTop is
            applied when its text changes (0, 0.0). */}
        {nav.stack.slice(1).map(() => <span className="hidden" />)}
        <div className={`${listFit ? `h-[${listFit.box}px] shrink-0` : 'flex-1 min-h-0'} overflow-y-auto ${t.page}`} scrollTop={view.left ? undefined : nav.n % 2 ? '0' : '0.0'}>
          {/* Every move to another page puts the page one place further in the
              tree, so the keys' ring and the layout's memory of the last page
              do not land on whatever the new page has there. */}
          {nav.n % 2 ? <span className="hidden" /> : null}
          {body}
        </div>
      </div>
      <Header t={t} z={z} sel={view.v === 'list' ? view.s : ''} canGoBack={nav.stack.length > 1} left={margin} right={margin} top={top} width={W - 2 * margin} />
    </div>
  )
}

// The frame's back (a swipe in from the left edge), forward, a long press of
// the green key and a keyboard's Backspace and page keys. Anything else is
// the keys': next and prev walk the stories and comments, Enter opens one.
export function onEvent(app, context) {
  const action = keyAction(context.event, context.payload)
  if (!action) return false
  const nav = navOf(app)
  const view = current(nav)
  if (action === 'reload') {
    retry()
    return true
  }
  if (action === 'back' && nav.stack.length > 1) {
    go(back(nav))
    return true
  }
  // Next and previous page: the list's, or the thread's.
  let pages = 1
  if (view.v === 'list') {
    const kept = frameos.recall('list') as any
    pages = kept && kept.data ? kept.data.pages : 1
  } else if (view.v === 'item') {
    const kept = frameos.recall('thread') as any
    pages = kept && kept.data ? threadPages(kept.data.comments, threadLimits(app).page, threadLimits(app).pageChars).length : 1
  }
  // Back on a later page of the first list is the page before it.
  const moved = turn(nav, action === 'next' ? 1 : -1, pages)
  if (moved === nav) return false
  go(moved)
  return true
}

sources.hn.ts:
// What the Hacker News reader works out without drawing anything: the API
// answers made small, the "3 hours ago" text, a comment's HTML as runs of
// text, the thread as a flat list, the views the reader walks through and
// what each key does. app.test.tsx tests all of it.

export const FIREBASE = 'https://hacker-news.firebaseio.com/v0'
export const ALGOLIA = 'https://hn.algolia.com/api/v1'
export const PER_PAGE = 30

export const SECTIONS = ['top', 'new', 'ask', 'show', 'jobs']
export const SECTION_LINKS = [
  { id: 'new', label: 'new' },
  { id: 'ask', label: 'ask' },
  { id: 'show', label: 'show' },
  { id: 'jobs', label: 'jobs' },
]

// ---------------------------------------------------------------- stories

// One story as the reader keeps it: short keys, nothing it does not draw.
export interface Story {
  id: number
  title: string
  url: string
  by: string
  score: number
  comments: number
  time: number
  kind: string // "story", "job", "poll"
}

export function storyFromHit(hit: any): Story | null {
  if (!hit || !hit.title) return null
  const tags: string[] = Array.isArray(hit._tags) ? hit._tags : []
  return {
    id: Number(hit.objectID),
    title: String(hit.title),
    url: hit.url ? String(hit.url) : '',
    by: hit.author ? String(hit.author) : '',
    score: Number(hit.points) || 0,
    comments: Number(hit.num_comments) || 0,
    time: Number(hit.created_at_i) || 0,
    kind: tags.includes('job') ? 'job' : 'story',
  }
}

export function storyFromItem(item: any): Story | null {
  if (!item || item.deleted || item.dead || !item.title) return null
  return {
    id: Number(item.id),
    title: String(item.title),
    url: item.url ? String(item.url) : '',
    by: item.by ? String(item.by) : '',
    score: Number(item.score) || 0,
    comments: Number(item.descendants) || 0,
    time: Number(item.time) || 0,
    kind: item.type === 'job' ? 'job' : item.type === 'poll' ? 'poll' : 'story',
  }
}

// The ids of one page of a ranked list (topstories and the like).
export const pageIds = (ids: any, page: number, perPage = PER_PAGE): number[] =>
  Array.isArray(ids) ? ids.slice(page * perPage, (page + 1) * perPage).map(Number) : []

// Algolia's search for exactly these stories, in one request.
export const algoliaStoriesUrl = (ids: number[]): string =>
  `${ALGOLIA}/search?tags=(story,poll),(${ids.map((id) => `story_${id}`).join(',')})` +
  `&hitsPerPage=${ids.length}&attributesToRetrieve=title,url,author,points,num_comments,created_at_i,_tags` +
  '&attributesToHighlight=none'

// The newest stories or jobs, a page at a time: what /newest and /jobs show.
export const algoliaByDateUrl = (tag: string, page: number, perPage = PER_PAGE): string =>
  `${ALGOLIA}/search_by_date?tags=${tag}&hitsPerPage=${perPage}&page=${page}` +
  '&attributesToRetrieve=title,url,author,points,num_comments,created_at_i,_tags&attributesToHighlight=none'

// The hits put back in the list's order; the ids Algolia did not have yet
// (a story a minute old) come back as missing, for the HN API.
export function orderStories(ids: number[], hits: any[]): { stories: (Story | null)[]; missing: number[] } {
  const byId = new Map<number, Story>()
  for (const hit of Array.isArray(hits) ? hits : []) {
    const story = storyFromHit(hit)
    if (story) byId.set(story.id, story)
  }
  const missing: number[] = []
  const stories = ids.map((id) => {
    const story = byId.get(id)
    if (!story) missing.push(id)
    return story || null
  })
  return { stories, missing }
}

// "github.com/frameos", "nytimes.com": what HN prints after a title.
const PATH_SITES = ['github.com', 'gitlab.com', 'twitter.com', 'x.com', 'medium.com', 'codeberg.org']
export function siteOf(url: string): string {
  const match = /^[a-z]+:\/\/([^/?#:]+)(?::\d+)?([^?#]*)/i.exec(url || '')
  if (!match) return ''
  const host = match[1].toLowerCase().replace(/^www\./, '')
  if (PATH_SITES.includes(host)) {
    const first = match[2].split('/').filter(Boolean)[0]
    if (first) return `${host}/${first.toLowerCase()}`
  }
  return host
}

// ------------------------------------------------------------------- time

const plural = (n: number, unit: string) => `${n} ${unit}${n === 1 ? '' : 's'} ago`

export function timeAgo(then: number, now: number): string {
  const s = Math.max(0, Math.floor(now - then))
  if (s < 3600) return plural(Math.max(1, Math.floor(s / 60)), 'minute')
  if (s < 86400) return plural(Math.floor(s / 3600), 'hour')
  if (s < 86400 * 31) return plural(Math.floor(s / 86400), 'day')
  if (s < 86400 * 365) return plural(Math.floor(s / (86400 * 30.4)), 'month')
  return plural(Math.floor(s / (86400 * 365.25)), 'year')
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
  'November', 'December']
export function dateText(seconds: number): string {
  const d = new Date(seconds * 1000)
  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`
}

// ------------------------------------------------------------ HTML of a comment

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' }
export function decodeEntities(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (whole, name: string) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      return Number.isFinite(code) && code > 0 && code < 0x110000 ? String.fromCodePoint(code) : whole
    }
    return ENTITIES[name.toLowerCase()] ?? whole
  })
}

// A comment as HN writes it (text, <p>, <i>, <a href>, <pre><code>) as
// blocks: a paragraph of runs, or a code block of lines. No markup is ever
// built back: the app draws these as JSX.
export interface Run {
  text: string
  italic?: boolean
  href?: string
}
export type Block = { kind: 'p'; runs: Run[] } | { kind: 'pre'; lines: string[] }

export function parseCommentHtml(html: string): Block[] {
  const blocks: Block[] = []
  let runs: Run[] = []
  let italic = 0
  let href = ''
  let pre: string[] | null = null
  const endParagraph = () => {
    const trimmed = runs.filter((run) => run.text.length > 0)
    if (trimmed.length && trimmed.some((run) => run.text.trim())) blocks.push({ kind: 'p', runs: trimmed })
    runs = []
  }
  const tag = /<(\/?)([a-z]+)([^>]*)>/gi
  let at = 0
  let match: RegExpExecArray | null
  const addText = (raw: string) => {
    if (!raw) return
    const text = decodeEntities(raw)
    if (pre) {
      pre.push(text)
      return
    }
    const run: Run = { text: text.replace(/\s+/g, ' ') }
    if (italic > 0) run.italic = true
    if (href) run.href = href
    runs.push(run)
  }
  while ((match = tag.exec(html || ''))) {
    addText(html.slice(at, match.index))
    at = tag.lastIndex
    const closing = match[1] === '/'
    const name = match[2].toLowerCase()
    if (name === 'p' && !closing && !pre) endParagraph()
    else if (name === 'i' || name === 'em') italic = Math.max(0, italic + (closing ? -1 : 1))
    else if (name === 'a') {
      if (closing) href = ''
      else {
        const found = /href\s*=\s*"([^"]*)"/i.exec(match[3]) || /href\s*=\s*'([^']*)'/i.exec(match[3])
        const link = found ? decodeEntities(found[1]) : ''
        href = /^(https?:\/\/|mailto:)/i.test(link) ? link : ''
      }
    } else if (name === 'pre') {
      if (!closing) {
        endParagraph()
        pre = []
      } else if (pre) {
        const lines = pre.join('').replace(/\n+$/, '').split('\n')
        blocks.push({ kind: 'pre', lines })
        pre = null
      }
    }
  }
  addText((html || '').slice(at))
  if (pre) blocks.push({ kind: 'pre', lines: pre.join('').replace(/\n+$/, '').split('\n') })
  endParagraph()
  return blocks
}

// Plain words of a comment (its HTML without the tags): for a cut and a test.
export const commentWords = (html: string): string =>
  parseCommentHtml(html)
    .map((b) => (b.kind === 'p' ? b.runs.map((r) => r.text).join('') : b.lines.join('\n')))
    .join('\n\n')

// A long comment cut at a tag boundary near `max` characters of HTML.
export function cutHtml(html: string, max: number): string {
  if (!html || html.length <= max) return html || ''
  let cut = html.lastIndexOf('<p>', max)
  if (cut < max / 2) cut = html.lastIndexOf(' ', max)
  if (cut < max / 2) cut = max
  const open = html.lastIndexOf('<', cut)
  if (open > html.lastIndexOf('>', cut)) cut = open
  const head = html.slice(0, cut)
  const tail = head.lastIndexOf('<pre>') > head.lastIndexOf('</pre>') ? '</code></pre>' : ''
  return `${head}${tail} …`
}

// ---------------------------------------------------------------- threads

// One comment of a thread, flat: its depth says how far in it is drawn, and
// `more` how many comments its subtree holds below it ("[4 more]").
export interface Comment {
  id: number
  by: string
  time: number
  depth: number
  html: string
  more: number
  dead?: boolean
}

export interface ThreadLimits {
  maxComments: number
  maxChars: number
}

// Algolia's tree (items/<id>: every comment with its children) as the flat
// list a page draws, top level in HN's order (`order`: the story's kids from
// the HN API; Algolia's are by age), at most `maxComments`, each comment's
// HTML cut to `maxChars`. Deleted comments with no replies are left out.
export function flattenThread(
  root: any,
  order: number[] | null,
  limits: ThreadLimits,
  into: Comment[] = [],
): { comments: Comment[]; cut: boolean } {
  let cut = false
  const rank = new Map<number, number>()
  ;(order || []).forEach((id, i) => rank.set(Number(id), i))
  const visit = (node: any, depth: number): number => {
    // Returns how many comments this subtree added (itself included).
    if (into.length >= limits.maxComments) {
      cut = true
      return 0
    }
    const kids: any[] = Array.isArray(node.children) ? node.children : []
    const gone = !node.author || node.text == null
    if (gone && kids.length === 0) return 0
    const at = into.length
    into.push({
      id: Number(node.id),
      by: node.author ? String(node.author) : '',
      time: Number(node.created_at_i) || 0,
      depth,
      html: gone ? '' : cutHtml(String(node.text), limits.maxChars),
      more: 0,
      dead: gone || undefined,
    })
    let added = 1
    for (const kid of kids) added += visit(kid, depth + 1)
    into[at].more = added - 1
    return added
  }
  const top: any[] = Array.isArray(root && root.children) ? root.children.slice() : []
  if (rank.size) top.sort((a, b) => (rank.get(Number(a.id)) ?? 1e9) - (rank.get(Number(b.id)) ?? 1e9))
  for (const node of top) visit(node, 0)
  return { comments: into, cut }
}

// Which comments a collapsed one hides: every one below a collapsed comment,
// down to the next comment at its depth or shallower.
export function hiddenFlags(comments: Comment[], folded: Set<number>): boolean[] {
  const hidden: boolean[] = new Array(comments.length).fill(false)
  let hideDeeperThan = Infinity
  for (let i = 0; i < comments.length; i++) {
    const c = comments[i]
    if (c.depth <= hideDeeperThan) hideDeeperThan = Infinity
    if (hideDeeperThan !== Infinity) {
      hidden[i] = true
      continue
    }
    if (folded.has(c.id)) hideDeeperThan = c.depth
  }
  return hidden
}

// Where each page of a thread starts: once a page holds `size` comments or
// `chars` characters of them, at the next top-level comment (a thread is read
// a subtree at a time), or anywhere once it holds twice that. Text is what a
// page costs a small frame's memory to lay out. Folds do not move them: a
// collapse only hides.
export function threadPages(comments: Comment[], size: number, chars = Infinity): number[] {
  const starts = [0]
  let count = 0
  let length = 0
  for (let i = 0; i < comments.length; i++) {
    const full = count >= size || length >= chars
    const overfull = count >= size * 2 || length >= chars * 2
    if (count > 0 && full && (comments[i].depth === 0 || overfull)) {
      starts.push(i)
      count = 0
      length = 0
    }
    count++
    length += comments[i].html.length + 40
  }
  return starts
}

// ------------------------------------------------------------------ views

// Where the reader is: a stack of views, the last one showing.
// `left`: another page was opened over this one, so going back to it keeps
// where it was scrolled to.
export type View =
  | { v: 'list'; s: string; p: number; left?: boolean }
  | { v: 'item'; id: number; p: number; from?: number; left?: boolean }
  | { v: 'user'; id: string; left?: boolean }

export interface Nav {
  stack: View[]
  n: number // moves by one at every change: the scroll box starts at the top again
}

const MAX_STACK = 8
export const startNav = (section: string): Nav => ({
  stack: [{ v: 'list', s: SECTIONS.includes(section) ? section : 'top', p: 0 }],
  n: 0,
})
export const current = (nav: Nav): View => nav.stack[nav.stack.length - 1]
export const push = (nav: Nav, view: View): Nav => ({
  stack: [...nav.stack.slice(0, -1), { ...current(nav), left: true }, view].slice(-MAX_STACK),
  n: nav.n + 1,
})
export const section = (nav: Nav, s: string): Nav => ({ stack: [{ v: 'list', s, p: 0 }], n: nav.n + 1 })
export const back = (nav: Nav): Nav => (nav.stack.length > 1 ? { stack: nav.stack.slice(0, -1), n: nav.n + 1 } : nav)
// The next page of a list or a thread, and the one before it.
export function turn(nav: Nav, by: number, pages: number): Nav {
  const view = current(nav)
  if (view.v === 'user') return nav
  const p = view.p + by
  if (p < 0 || p >= pages) return nav
  return { stack: [...nav.stack.slice(0, -1), { ...view, p, left: false }], n: nav.n + 1 }
}

export function readNav(kept: any, start: string): Nav {
  if (kept && Array.isArray(kept.stack) && kept.stack.length && typeof kept.n === 'number') return kept as Nav
  return startNav(start)
}

// ------------------------------------------------------------------- keys

// What a key does beyond the frame's own keys (docs/jsx-ui.md "Keys": a
// frame's next and prev buttons, Tab and Shift+Tab, walk the stories and
// comments, and Enter opens one). Null: not ours, the keys take it.
export type KeyAction = 'back' | 'next' | 'prev' | 'reload' | null

export function keyAction(event: string, payload: any): KeyAction {
  const p = payload || {}
  if (event === 'back') return 'back'
  if (event === 'forward') return 'next'
  if (event === 'button') {
    // A long press of the green key (the reTerminal E1004's, which has no
    // microphone to give it to), or a back key: back.
    if (p.action === 'longPress' && (p.role === 'primary' || p.role === 'refresh')) return 'back'
    if (p.role === 'back' && (p.action === 'press' || p.action === 'doublePress' || !p.action)) return 'back'
    return null
  }
  if (event === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return null
    switch (p.key) {
      case 'Backspace':
      case 'ArrowLeft':
      case 'h':
      case 'b':
        return 'back'
      case 'PageDown':
      case 'ArrowRight':
      case 'n':
      case 'l':
        return 'next'
      case 'PageUp':
      case 'p':
        return 'prev'
      case 'r':
        return 'reload'
    }
  }
  return null
}

