// Fetching, straight from the frame: the HN API for the ranked lists and the
// order of a thread, Algolia's HN search for the stories of a page in one
// request and a whole comment tree in another. Every answer is cut down to
// what the reader draws before it is kept.
import {
  ALGOLIA,
  FIREBASE,
  PER_PAGE,
  algoliaByDateUrl,
  algoliaStoriesUrl,
  flattenThread,
  orderStories,
  pageIds,
  storyFromItem,
} from './hn'
import type { Comment, Story } from './hn'

export interface ListData {
  key: string
  at: number
  pages: number
  stories: Story[]
}

export interface ThreadData {
  id: number
  at: number
  story: Story
  text: string
  comments: Comment[]
  // The comments not loaded: a thread too big to fetch whole on this frame
  // comes a few top-level subtrees at a time (`kids`, from `next`).
  kids: number[]
  next: number
  cut: boolean
}

export interface UserData {
  id: string
  at: number
  karma: number
  created: number
  about: string
}

const json = (url: string): any => frameos.fetchJson(url)

const nowSeconds = () => Math.floor(Date.now() / 1000)

export function fetchList(sectionId: string, page: number, perPage = PER_PAGE): ListData {
  const key = `${sectionId}:${page}:${perPage}`
  if (sectionId === 'new' || sectionId === 'jobs') {
    const answer = json(algoliaByDateUrl(sectionId === 'jobs' ? 'job' : 'story', page, perPage))
    if (!answer || !Array.isArray(answer.hits)) throw new Error('Hacker News did not answer')
    const { stories } = orderStories(
      answer.hits.map((hit: any) => Number(hit.objectID)),
      answer.hits,
    )
    return { key, at: nowSeconds(), pages: Math.min(Number(answer.nbPages) || 1, 10), stories: stories.filter(Boolean) as Story[] }
  }
  const ids = json(`${FIREBASE}/${sectionId}stories.json`)
  if (!Array.isArray(ids)) throw new Error('Hacker News did not answer')
  const wanted = pageIds(ids, page, perPage)
  const pages = Math.max(1, Math.ceil(ids.length / perPage))
  if (!wanted.length) return { key, at: nowSeconds(), pages, stories: [] }
  const answer = json(algoliaStoriesUrl(wanted))
  const { stories, missing } = orderStories(wanted, answer && answer.hits)
  // Stories Algolia does not have yet (minutes old) or never indexes (a job
  // ad on the front page) come one by one from the HN API, a few at most.
  for (const id of missing.slice(0, 8)) {
    const story = storyFromItem(json(`${FIREBASE}/item/${id}.json`))
    if (story) stories[wanted.indexOf(id)] = story
  }
  return { key, at: nowSeconds(), pages, stories: stories.filter(Boolean) as Story[] }
}

export interface ThreadLimitsOnFrame {
  maxComments: number
  maxChars: number
  // The most comments one request may hold on this frame (a whole tree is
  // parsed at once): more than that, and the thread comes in subtrees.
  wholeUpTo: number
}

export function fetchThread(id: number, limits: ThreadLimitsOnFrame, from = 0): ThreadData {
  // The story and its top-level comments in HN's order (Algolia's are by age).
  const item = json(`${FIREBASE}/item/${id}.json`)
  let story = storyFromItem(item)
  const kids: number[] = item && Array.isArray(item.kids) ? item.kids.map(Number) : []
  let text = item && item.text ? String(item.text) : ''
  const comments: Comment[] = []
  let cut = false
  let next = kids.length
  if (!story || story.comments <= limits.wholeUpTo) {
    const tree = json(`${ALGOLIA}/items/${id}`)
    if (!tree && !story) throw new Error('Hacker News did not answer')
    if (tree) {
      if (!story) {
        story = {
          id,
          title: String(tree.title || ''),
          url: tree.url ? String(tree.url) : '',
          by: tree.author ? String(tree.author) : '',
          score: Number(tree.points) || 0,
          comments: 0,
          time: Number(tree.created_at_i) || 0,
          kind: tree.type === 'job' ? 'job' : 'story',
        }
        text = tree.text ? String(tree.text) : ''
      }
      cut = flattenThread(tree, kids, limits, comments).cut
      if (!story.comments) story.comments = comments.length
    }
  } else {
    // A big thread: one top-level comment's subtree a request, until the
    // page's share is in.
    next = from
    for (let requests = 0; next < kids.length && requests < 12 && comments.length < limits.maxComments; requests++) {
      const tree = json(`${ALGOLIA}/items/${kids[next]}`)
      next++
      if (tree) flattenThread({ children: [tree] }, null, limits, comments)
    }
    cut = next < kids.length
  }
  return { id, at: nowSeconds(), story: story as Story, text, comments, kids: cut ? kids : [], next, cut }
}

export function fetchUser(id: string): UserData {
  const name = encodeURIComponent(id)
  const user = json(`${ALGOLIA}/users/${name}`)
  if (!user || !user.username) throw new Error(`No such user: ${id}`)
  // The HN API's whole user lists every submission; only this one number of it.
  const created = json(`${FIREBASE}/user/${name}/created.json`)
  return {
    id: String(user.username),
    at: nowSeconds(),
    karma: Number(user.karma) || 0,
    created: Number(created) || 0,
    about: user.about ? String(user.about) : '',
  }
}

sources.app.test.tsx:
import { get, onEvent } from './app'
import {
  back,
  current,
  cutHtml,
  flattenThread,
  hiddenFlags,
  keyAction,
  orderStories,
  parseCommentHtml,
  push,
  section,
  siteOf,
  startNav,
  storyFromItem,
  threadPages,
  timeAgo,
  turn,
} from './hn'

// Every string in a tree, in order.
function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false || node === true) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}
const said = (tree: any) => texts(tree).join('')

// The first element whose own words (children included) contain `words` and
// that takes a tap.
function tappable(node: any, words: string): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = tappable(child, words)
      if (hit) return hit
    }
    return null
  }
  if (!node.props) return null
  const inner = tappable(node.props.children, words)
  if (inner) return inner
  return typeof node.props.onClick === 'function' && said(node).includes(words) ? node : null
}

// A memo()'d component comes back as an element whose type is a function:
// run it the way the runtime would, so the tree can be read.
function expand(node: any): any {
  if (Array.isArray(node)) return node.map(expand)
  if (!node || typeof node !== 'object') return node
  if (typeof node.type === 'function') return expand(node.type({ ...node.props }))
  if (!node.props) return node
  return { ...node, props: { ...node.props, children: expand(node.props.children) } }
}

const NOW = 1795300000

// Hacker News as the two APIs answer, for one story with a small thread.
const TOP = [101, 102, 103]
const HITS = {
  hits: [
    { objectID: '102', title: 'Second story', url: 'https://www.example.org/b', author: 'bob', points: 5, num_comments: 1, created_at_i: NOW - 7200, _tags: ['story'] },
    { objectID: '101', title: 'First story', url: 'https://github.com/frameos/frameos', author: 'ann', points: 120, num_comments: 3, created_at_i: NOW - 600, _tags: ['story'] },
  ],
}
const ITEM_103 = { id: 103, type: 'job', title: 'FrameOS is hiring', by: 'yc', time: NOW - 86400, url: 'https://jobs.example.com' }
const ITEM_101 = { id: 101, type: 'story', title: 'First story', by: 'ann', score: 120, descendants: 3, time: NOW - 600, url: 'https://github.com/frameos/frameos', kids: [12, 11] }
const TREE_101 = {
  id: 101, title: 'First story', author: 'ann', points: 120, created_at_i: NOW - 600,
  children: [
    { id: 11, author: 'cat', text: 'Older top comment', created_at_i: NOW - 500, children: [
      { id: 13, author: 'dan', text: 'A reply with <i>emphasis</i>', created_at_i: NOW - 400, children: [] },
    ] },
    { id: 12, author: 'eve', text: 'Ranked first<p>with <a href="https://frameos.net">a link</a>', created_at_i: NOW - 300, children: [] },
  ],
}

let fetched: string[] = []
function serve() {
  fetched = []
  return mock.frameos('fetchJson', (url: string) => {
    fetched.push(url)
    if (url.endsWith('/topstories.json')) return TOP
    if (url.includes('/search?')) return HITS
    if (url.endsWith('/item/103.json')) return ITEM_103
    if (url.endsWith('/item/101.json')) return ITEM_101
    if (url.endsWith('/items/101')) return TREE_101
    return null
  })
}
const show = (app: any) => expand(get(app, makeContext()))

describe('the API answers', () => {
  it('puts Algolia hits back in the ranked order and names what is missing', () => {
    const { stories, missing } = orderStories(TOP, HITS.hits)
    expect(stories.map((s) => s && s.title)).toEqual(['First story', 'Second story', null])
    expect(missing).toEqual([103])
  })

  it('reads an HN API item, a job included, and skips the dead', () => {
    const job = storyFromItem(ITEM_103)
    expect(job.kind).toBe('job')
    expect(job.title).toBe('FrameOS is hiring')
    expect(storyFromItem({ id: 1, dead: true, title: 'x' })).toBeNull()
  })

  it('prints a site the way HN does', () => {
    expect(siteOf('https://www.nytimes.com/2026/a.html')).toBe('nytimes.com')
    expect(siteOf('https://github.com/FrameOS/frameos/pull/1')).toBe('github.com/frameos')
    expect(siteOf('')).toBe('')
  })
})

describe('ages', () => {
  it('counts in minutes, hours, days, months and years', () => {
    expect(timeAgo(NOW - 20, NOW)).toBe('1 minute ago')
    expect(timeAgo(NOW - 600, NOW)).toBe('10 minutes ago')
    expect(timeAgo(NOW - 3600, NOW)).toBe('1 hour ago')
    expect(timeAgo(NOW - 3 * 86400, NOW)).toBe('3 days ago')
    expect(timeAgo(NOW - 70 * 86400, NOW)).toBe('2 months ago')
    expect(timeAgo(NOW - 800 * 86400, NOW)).toBe('2 years ago')
  })
})

describe("a comment's HTML", () => {
  it('reads paragraphs, italics, links and entities', () => {
    const blocks = parseCommentHtml('It&#x27;s <i>fine</i> &amp; good<p>See <a href="https:&#x2F;&#x2F;frameos.net" rel="nofollow">frameos.net</a>')
    expect(blocks).toHaveLength(2)
    expect(blocks[0]).toEqual({ kind: 'p', runs: [{ text: "It's " }, { text: 'fine', italic: true }, { text: ' & good' }] })
    expect(blocks[1]).toEqual({ kind: 'p', runs: [{ text: 'See ' }, { text: 'frameos.net', href: 'https://frameos.net' }] })
  })

  it('keeps a code block line by line, indentation and all', () => {
    const blocks = parseCommentHtml('Try:<p><pre><code>  if (x) {\n    y()\n  }\n</code></pre>')
    expect(blocks[1]).toEqual({ kind: 'pre', lines: ['  if (x) {', '    y()', '  }'] })
  })

  it('drops links that are no web or mail address', () => {
    const blocks = parseCommentHtml('<a href="javascript:alert(1)">x</a>')
    expect(blocks[0].kind === 'p' && blocks[0].runs[0].href).toBeFalsy()
  })

  it('cuts a long comment between words, never inside a tag', () => {
    const cut = cutHtml(`${'word '.repeat(50)}<a href="https://x.y">link</a>`, 260)
    expect(cut.endsWith(' …')).toBe(true)
    expect(cut).not.toContain('<a href')
  })
})

describe('a thread', () => {
  const flat = flattenThread(TREE_101, [12, 11], { maxComments: 100, maxChars: 1000 }).comments

  it('is flat, top level in HN rank order, with depths and subtree sizes', () => {
    expect(flat.map((c) => [c.id, c.depth, c.more])).toEqual([[12, 0, 0], [11, 0, 1], [13, 1, 0]])
  })

  it('stops at the frame limit', () => {
    const { comments, cut } = flattenThread(TREE_101, null, { maxComments: 2, maxChars: 1000 })
    expect(comments).toHaveLength(2)
    expect(cut).toBe(true)
  })

  it('hides what a collapsed comment holds, and nothing else', () => {
    expect(hiddenFlags(flat, new Set([11]))).toEqual([false, false, true])
    expect(hiddenFlags(flat, new Set([12]))).toEqual([false, false, false])
  })

  it('pages at top-level comments', () => {
    const many = Array.from({ length: 10 }, (_, i) => ({ id: i, by: 'a', time: 0, depth: i % 2, html: 'x', more: 0 }))
    expect(threadPages(many, 3)).toEqual([0, 4, 8])
    expect(threadPages(many, 100)).toEqual([0])
  })
})

describe('where the reader is', () => {
  it('opens, goes back and turns pages', () => {
    let nav = startNav('top')
    nav = push(nav, { v: 'item', id: 1, p: 0 })
    expect(current(nav)).toEqual({ v: 'item', id: 1, p: 0 })
    expect(nav.stack[0].left).toBe(true)
    nav = turn(nav, 1, 3)
    expect(current(nav)).toMatchObject({ v: 'item', p: 1 })
    expect(turn(nav, 5, 3)).toBe(nav)
    nav = back(nav)
    expect(current(nav)).toMatchObject({ v: 'list', s: 'top' })
    expect(back(nav)).toBe(nav)
    expect(current(section(nav, 'ask'))).toEqual({ v: 'list', s: 'ask', p: 0 })
  })

  it('takes a key as back, next or prev, and leaves the ring its keys', () => {
    expect(keyAction('button', { role: 'primary', action: 'longPress' })).toBe('back')
    expect(keyAction('button', { role: 'next', action: 'press' })).toBeNull()
    expect(keyAction('button', { role: 'primary', action: 'press' })).toBeNull()
    expect(keyAction('keyDown', { key: 'Backspace' })).toBe('back')
    expect(keyAction('keyDown', { key: 'Tab' })).toBeNull()
    expect(keyAction('keyDown', { key: 'n' })).toBe('next')
    expect(keyAction('keyDown', { key: 'n', ctrl: true })).toBeNull()
    expect(keyAction('back', {})).toBe('back')
    expect(keyAction('forward', {})).toBe('next')
  })
})

describe('the reader', () => {
  it('draws the front page in rank order, the job from the HN API', () => {
    serve()
    const words = said(show(makeApp()))
    expect(words).toContain('Hacker News')
    expect(words.indexOf('First story')).toBeLessThan(words.indexOf('Second story'))
    expect(words).toContain('(github.com/frameos)')
    expect(words).toContain('FrameOS is hiring')
    expect(fetched.some((url) => url.endsWith('/item/103.json'))).toBe(true)
  })

  it('opens a story, collapses a comment and goes back without fetching the list again', () => {
    serve()
    const app = makeApp()
    tappable(show(app), 'First story').props.onClick({})
    let tree = show(app)
    expect(said(tree)).toContain('Ranked first')
    expect(said(tree).indexOf('Ranked first')).toBeLessThan(said(tree).indexOf('Older top comment'))
    tappable(tree, 'Older top comment').props.onClick({})
    tree = show(app)
    expect(said(tree)).toContain('[2 more]')
    expect(said(tree)).not.toContain('Older top comment')
    const before = fetched.length
    expect(onEvent(app, makeContext({ event: 'button', payload: { role: 'primary', action: 'longPress' } }))).toBe(true)
    expect(said(show(app))).toContain('Second story')
    expect(fetched.length).toBe(before)
  })

  it('says so when Hacker News does not answer', () => {
    mock.frameos('fetchJson', () => null)
    expect(said(show(makeApp()))).toContain('Could not reach Hacker News')
  })
})
